struct Ride { let id: Int; let minutes: Int }
protocol RidePricing { func amount(_ ride: Ride) -> Int }
struct MeteredPrice: RidePricing {
    func amount(_ ride: Ride) -> Int { ride.minutes * 2 }
}
struct PassPrice: RidePricing {
    func amount(_ ride: Ride) -> Int { 30 }
}
protocol ReceiptSharing { func share(id: Int, text: String) }
final class ShareLog: ReceiptSharing {
    var messages: [Int: String] = [:]
    func share(id: Int, text: String) { messages[id] = text }
}
struct QuoteShare {
    let pricing: any RidePricing
    let sharing: any ReceiptSharing
    func sendPreview(_ ride: Ride) {
        let text = "Предпросмотр: \(pricing.amount(ride))"
        sharing.share(id: ride.id, text: text)
    }
}
let log = ShareLog()
let share = QuoteShare(pricing: MeteredPrice(), sharing: log)
share.sendPreview(Ride(id: 12, minutes: 5))
assert(log.messages[12] == "Предпросмотр: 10")

